 "content": "def transform(grid):
    # Split repeated color objects by 4-connectivity. The two objects of each color
    # swap vertical positions; each object's pixels retain their relative locations,
    # translated to the corresponding object's original top-left alignment region.
    from collections import deque, defaultdict
    h, w = len(grid), len(grid[0])
    comps = defaultdict(list)
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps[color].append(cells)
    out=[[0]*w for _ in range(h)]
    for color, objects in comps.items():
        # Instances are in upper/lower bands. Objects exchange bands: translate each
        # component so its bounding box starts at the other component's top row.
        objects.sort(key=lambda cells:min(r for r,c in cells))
        if len(objects)!=2:
            for cells in objects:
                for r,c in cells: out[r][c]=color
            continue
        a,b=objects
        atop=min(r for r,c in a); btop=min(r for r,c in b)
        for cells, target in ((a,btop),(b,atop)):
            top=min(r for r,c in cells)
            for r,c in cells:
                rr=r+(target-top)
                if 0<=rr<h: out[rr][c]=color
    return out
"
}

